   "title": "ஒரு முழுத் தொடரை தொகுப்பாக மாற்றுவது எப்படி – எவை சாத்தியம், எவை சாத்தியமில்லை – AI-SRTSub",
   "desc": "ஒரு முழுத் தொடருக்கும் பொதுவாக ஒரே மாற்றம் தேவைப்படும்: ஒரே வடிவம், நேர இடைவெளி, கலைச்சொற்கள். எந்தப் பணிகள் ஒரே கட்டத்தில் முடியும், எவை முடியாது மற்றும் பகுப்பாய்வு செய்யத் தவறிய கோப்புகளை எவ்வாறு கையாள்வது என்பது இங்கே.",
