     "இரண்டு கோப்புகளும் ஒரே வரிசையில் ஒரே எண்ணிக்கையிலான உள்ளீடுகளைக் கொண்டிருக்கும் போது, வரிசைப்படி இணைப்பதே மிகவும் பாதுகாப்பானது. எண்ணிக்கைகள் வேறுபடும் போது (ஒரு பக்கம் உள்ளீடுகளை இணைத்துள்ளது, மற்றொன்று பிரித்துள்ளது), காலவரிசைப்படி இணைத்து, நெருக்கத்தின் அடிப்படையில் கருவியைப் பொருத்த அனுமதிக்கவும். எந்தக் காலவரிசையைப் பயன்படுத்துவது என்பது எந்தக் கோப்பு மிகவும் துல்லியமானது என்பதைப் பொறுத்தது — பொதுவாக அசல் கோப்பு.",
