     "**ஏற்றுமதி செய்யப்பட்ட ASS இல் உள்ள பாணியை ஒரு பிளேயர் புறக்கணித்தால் என்ன செய்வது?** பாணிகள் கோப்புக்குள் சேமிக்கப்படும், ஆனால் ASSக்கான பிளேயர் ஆதரவு மாறுபடும். உங்களுக்கு மிகவும் எடுத்துச் செல்லக்கூடிய தோற்றம் தேவைப்பட்டால், இருமொழி VTT பாணியை ஏற்றுமதி செய்யவும்.",
     "**இதை மாற்றிவிட்ட பிறகு ஆரம்ப வார்ப்புமுக்கு எப்படி திரும்புவது?** ASS தொகுதியில் உள்ள \"இயல்புநிலை அளவுருக்களை மீட்டமை\" மற்றும் VTT தொகுதியில் உள்ள \"வார்ப்புரு இயல்புநிலைகளை மீட்டமை\" ஆகியவை அந்தந்தப் பகுதிகளை மீட்டமைக்கும்.",
