     "[[எளிய-மரபுவழி மாற்றம்|/hanconv.html]] ஐத் திறக்கவும், வசனத்தை இழுத்து விடவும், \"Convert to\" என்பதன் கீழ் எளிய → மரபுவழி திசைகளில் ஒன்றைத் தேர்ந்தெடுக்கவும்: பொதுவான மரபுவழி, தைவானிய (சொற்களை மாற்றுதல்), தைவானிய (எழுத்துருக்கள் மட்டும்) அல்லது ஹொங்கொங். மாற்றம் உடனடியாக நிகழ்கிறது மற்றும் முடிவுப் பகுதி முடிக்கப்பட்ட வசனத்தைக் காட்டுகிறது, பதிவிறக்கத் தயாராக உள்ளது.",
     "**தைவானிய பார்வையாளர்களுக்கு**: பிராந்திய சொற்களஞ்சியமும் மாற வேண்டும் என்றால் \"Taiwanese (change wording)\" என்பதைத் தேர்ந்தெடுக்கவும் — \"மென்பொருள்\" மற்றும் \"தகவல்\" ஆகியவை அவைகளின் தைவானிய சமமானவையாக மாறும் — அல்லது உங்கள் அசல் சொற்களை வைத்துக்கொண்டு எழுத்து வடிவங்கள் மாற வேண்டும் என்றால் \"Taiwanese (glyphs only)\" என்பதைத் தேர்ந்தெடுக்கவும். **ஹொங்கொங் பார்வையாளர்களுக்கு**: \"Hong Kong\" என்பதைத் தேர்ந்தெடுக்கவும், அங்கு \"மென்பொருள்\" இன்னும் வேறு வடிவத்தில் எழுதப்பட்டுள்ளது."
