   "desc": "ஐந்து பொதுவான உபதலைப்பு வடிவங்களின் திறன் ஒப்பீடு: உரை நடை, நிலைப்படுத்தல், நேரத் துல்லியம், ஒவ்வொன்றும் எங்கு பொருந்தும் மற்றும் அவற்றுக்கிடையே எப்படி மாற்றுவது.",
   "h1": "உபதலைப்பு வடிவத்தைத் தேர்ந்தெடுத்தல்: SRT / VTT / ASS / SBV / LRC",
   "intro": "ஐந்து வடிவங்களில் சேமிக்கப்பட்ட அதே உபதலைப்பு ஐந்து வெவ்வேறு தேவைகளைப் பூர்த்தி செய்கிறது. ஒவ்வொரு வடிவமும் என்ன செய்ய முடியும் மற்றும் அவற்றுக்கிடையே எவ்வாறு மாறுவது என்பதை இந்த வழிகாட்டி ஒப்பிடுகிறது.",
